export function validateOrder(order) {
  if (!order || typeof order !== 'object' || !Array.isArray(order.lines) || order.lines.length === 0) {
    throw new Error('INVALID_ORDER');
  }
  for (const line of order.lines) {
    if (!line || typeof line !== 'object') throw new Error('INVALID_ORDER');
    if (typeof line.sku !== 'string') throw new Error('INVALID_ORDER');
    if (!Number.isInteger(line.quantity) || line.quantity <= 0) throw new Error('INVALID_ORDER');
  }
  return order;
}

import { validateOrder } from './contract.mjs';
const prices = { A: 125, B: 300 };
export function quote(order) {
  validateOrder(order);
  const items = [];
  let totalCents = 0;
  for (const line of order.lines) {
    if (!Object.hasOwn(prices, line.sku)) throw new Error('UNKNOWN_SKU');
    const lineCents = prices[line.sku] * line.quantity;
    items.push({ sku: line.sku, quantity: line.quantity, lineCents });
    totalCents += lineCents;
  }
  return { items, totalCents };
}
